return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n % 10 != 1 || n % 100 == 11;','language'=>'is_IS','project-id-version'=>'Babilim 1.0.0','pot-creation-date'=>'2026-10-31T05:53:18+00:00','po-revision-date'=>'2026-10-31T05:53:18+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Fyllir inn vantandi þýðingar fyrir viðbæturnar og þemun sem þegar eru uppsett á vefnum þínum.','Translations'=>'Þýðingar','Babilim Settings'=>'Babilim stillingar','Settings'=>'Stillingar','You are not allowed to do this.'=>'Þú hefur ekki heimild til að gera þetta.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Veldu færri einingar: að hámarki %1$d aðgerðir í hverri keyrslu (þú valdir %2$d).','That component is not installed on this site, so a translation cannot be requested for it.'=>'Þessi eining er ekki uppsett á þessum vef, því er ekki hægt að biðja um þýðingu fyrir hana.','Already installed.'=>'Þegar uppsett.','Downloaded and installed.'=>'Sótt og uppsett.','Babilim has not been enabled for this site yet.'=>'Babilim hefur ekki enn verið virkjað fyrir þennan vef.','No build is available to download for this locale.'=>'Engin útgáfa er tiltæk til niðurhals fyrir þessa staðfærslu.','Rolled back to the previous build.'=>'Sneri aftur í fyrri útgáfu.','Rolled back and reported.'=>'Sneri til baka og tilkynnti.','Rolled back, but the report could not be sent: %s'=>'Sneri til baka, en ekki tókst að senda tilkynninguna: %s','Removed.'=>'Fjarlægt.','Translation requested.'=>'Beðið um þýðingu.','This component was already uploaded. Babilim is checking it now.'=>'Þessari einingu var þegar hlaðið upp. Babilim er að athuga hana núna.','Upload cancelled.'=>'Hætt við upphleðslu.','Upload complete — translation requested.'=>'Upphleðslu lokið — beðið um þýðingu.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Þessi eining tilgreinir ekki útgáfunúmer, því er ekki hægt að biðja um þýðingu fyrir hana.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Útgáfunúmer þessarar einingar er lengra en %d stafir, sem Babilim ræður ekki við, því er ekki hægt að biðja um þýðingu fyrir hana.','A translation cannot be requested for that locale on this site right now.'=>'Ekki er hægt að biðja um þýðingu fyrir þessa staðfærslu á þessum vef eins og er.','Thank you. Your report was sent.'=>'Takk fyrir. Tilkynningin þín var send.','This report does not name a valid plugin or theme and locale.'=>'Þessi skýrsla nefnir hvorki gilda viðbót eða þema né staðfærslu.','Please choose a category for this report.'=>'Veldu flokk fyrir þessa tilkynningu.','This report is missing a valid build to report against.'=>'Þessa tilkynningu vantar gilda útgáfu til að tilkynna um.','This build is not one this site currently knows about for this component/locale.'=>'Þessi útgáfa er ekki ein af þeim sem þessi vefur þekkir núna fyrir þessa einingu og staðfærslu.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Reiturinn „%1$s“ er of langur: hann hefur %2$d stafi og hámarkið er %3$d. Engu var sent; styttu hann og reyndu aftur.','Original string'=>'Upprunalegur strengur','String context'=>'Samhengi strengs','Current translation'=>'Núverandi þýðing','Suggested translation'=>'Tillaga að þýðingu','Note (optional)'=>'Athugasemd (valfrjálst)','Where you saw this (optional)'=>'Hvar þú sást þetta (valfrjálst)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Þjónustan seinkar samstillingu Babilim tímabundið (hraðatakmörkun); það reynir aftur eftir %s.','That is not a valid WordPress locale code. Nothing was saved.'=>'Þetta er ekki gildur WordPress staðfærslukóði. Engu var vistað.','Settings saved.'=>'Stillingar vistaðar.','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Ef kveikt er á þessu eyðir fjarlæging einnig auðkenni þessa vefs. Ekki er hægt að endurheimta greidda leyfið sem tengt er þessum vef sjálfkrafa eftir það; þú þyrftir að hafa samband við þjónustuver Babilim á %s til að fá það aftur.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim er stillt á að eyða auðkenni þessa vefs þegar viðbótinni er eytt. Þá væri ekki hægt að endurheimta greidda leyfið sem tengt er þessum vef sjálfkrafa; þú þyrftir að hafa samband við þjónustuver Babilim á %s. Til að halda auðkenninu skaltu ýta á Hætta við, taka hakið af „Eyða öllum Babilim gögnum við fjarlægingu“ í Babilim stillingum og afvirkja aftur. Afvirkja samt?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d vefur á þessu neti er stilltur á að eyða Babilim auðkenni sínu þegar viðbótinni er eytt. Þá væri ekki hægt að endurheimta greidda leyfið sem tengt er þeim vef sjálfkrafa; þú þyrftir að hafa samband við þjónustuver Babilim á %2$s. Til að halda auðkenninu skaltu ýta á Hætta við, taka hakið af „Eyða öllum Babilim gögnum við fjarlægingu“ í Babilim stillingum þess vefs og afvirkja aftur. Afvirkja samt?' . "\0" . '%1$d vefir á þessu neti eru stilltir á að eyða Babilim auðkenni sínu þegar viðbótinni er eytt. Þá væri ekki hægt að endurheimta greidda leyfið sem tengt er þeim vefjum sjálfkrafa; þú þyrftir að hafa samband við þjónustuver Babilim á %2$s. Til að halda auðkennunum skaltu ýta á Hætta við, taka hakið af „Eyða öllum Babilim gögnum við fjarlægingu“ í Babilim stillingum hvers vefs og afvirkja aftur. Afvirkja samt?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Þetta net hefur of marga vefi til að hægt sé að athuga þá einn og einn og sumir þeirra gætu verið stilltir á að eyða Babilim auðkenni sínu þegar viðbótinni er eytt. Þá væri ekki hægt að endurheimta greidda leyfið sem tengt er slíkum vef sjálfkrafa; þú þyrftir að hafa samband við þjónustuver Babilim á %s. Til að halda auðkennunum skaltu ýta á Hætta við, taka hakið af „Eyða öllum Babilim gögnum við fjarlægingu“ í Babilim stillingum hvers vefs og afvirkja aftur. Afvirkja samt?','Open Babilim settings'=>'Opna Babilim stillingar','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim gat ekki staðfest þessa vefsíðu, því er engu hlaðið niður eða sett upp.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Þjónustan náði ekki sambandi við vefinn þinn. Líklega er eldveggur, öryggisviðbót eða regla hjá vefhýsingu að loka á beiðnina; leyfðu beiðnir til /wp-json/babilim/v1/challenge.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Vefsíðan þín var of lengi að svara. Reyndu aftur síðar og athugaðu hvort vefhýsingin sé of hæg eða yfirhlaðin.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Vefurinn þinn svaraði, en ekki með því sem búist var við. Önnur viðbót gæti verið að endurskrifa REST API, eða endapunkturinn gæti verið í skyndiminni; undanskildu /wp-json/babilim/v1/challenge frá skyndiminni og endurskrifun.','Please check that your site can be reached from the internet, then try again.'=>'Athugaðu hvort hægt sé að ná í vefsíðuna þína af internetinu og reyndu svo aftur.','Re-verify'=>'Staðfesta aftur','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Þessi vefsíða er stærri en þjónustan tekur við í einni samstillingu, því var sumu sleppt: %1$d einingum og %2$d tungumálum.','This site is verified.'=>'Þessi vefur er staðfestur.','Registration restarted.'=>'Skráning hófst að nýju.','Sync complete.'=>'Samstillingu lokið.','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim er að virkja og athuga þessa vefsíðu… Endurhlaðið þessa síðu eða bíðið eftir að tímasetta athugunin klárist.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim gat ekki lokið virkjun (%1$s): %2$s','A host that serves only one PHP request at a time cannot complete this step.'=>'Vefhýsing sem afgreiðir aðeins eina PHP-beiðni í einu getur ekki lokið þessu skrefi.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim er virkt: þessi vefur er staðfestur og %d eining fannst.' . "\0" . 'Babilim er virkt: þessi vefur er staðfestur og %d einingar fundust.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim er óvirkt. Engu meira er sent; þýðingar sem þegar eru uppsettar halda áfram að virka.','Supplementary translation index rebuilt.'=>'Viðbótarþýðingaskrá endurbyggð.','Sweep complete: %d file deleted.'=>'Hreinsun lokið: %d skrá eytt.' . "\0" . 'Hreinsun lokið: %d skrám eytt.','Removed %d installed component.'=>'%d uppsett eining fjarlægð.' . "\0" . '%d uppsettar einingar fjarlægðar.','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Sjálfvirkar uppsetningar eru nú óvirkar; kveiktu aftur á þeim í stillingunum ef þú vilt.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim finnur viðbætur og þemu á þessari vefsíðu sem hafa enga þýðingu fyrir tungumálið þitt og setur upp eina fyrir hvert.','Languages found on this site: %s.'=>'Tungumál sem fundust á þessari vefsíðu: %s.','Available translations can be installed with one click, and missing ones can be requested. After that, new translations and updates are installed automatically (on the free plan, only for plugins and themes that already use a free slot).'=>'Hægt er að setja upp tiltækar þýðingar með einum smelli og óska eftir þeim sem vantar. Eftir það eru nýjar þýðingar og uppfærslur settar upp sjálfkrafa (í ókeypis áskrift aðeins fyrir viðbætur og þemu sem nýta nú þegar ókeypis úthlutun).','The free plan covers a limited number of plugins and themes; your exact quota is shown in Settings after you enable Babilim.'=>'Ókeypis áskriftin nær yfir takmarkaðan fjölda viðbóta og þema; nákvæmur kvóti þinn birtist í Stillingum eftir að þú virkjar Babilim.','What is sent when you enable Babilim'=>'Hvað er sent þegar þú virkjar Babilim','Enabling…'=>'Verið er að virkja…','Enable Babilim'=>'Virkja Babilim','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Með því að smella á Virkja samþykkir þú að senda upplýsingarnar hér að ofan til Babilim.','Check again now'=>'Athuga aftur núna','Babilim installed %d translation automatically since your last visit.'=>'Babilim setti upp %d þýðingu sjálfkrafa frá síðustu heimsókn þinni.' . "\0" . 'Babilim setti upp %d þýðingar sjálfkrafa frá síðustu heimsókn þinni.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim er að virkja og athuga þessa vefsíðu… (síðasta tilraun: %s)','Check again'=>'Athuga aftur','No components synced yet.'=>'Engar einingar hafa verið samstilltar enn.','%d succeeded'=>'%d tókst' . "\0" . '%d tókust','%d skipped'=>'%d sleppt' . "\0" . '%d sleppt','%d failed'=>'%d mistókst' . "\0" . '%d mistókust','%d not yet tried'=>'%d ekki reynt enn' . "\0" . '%d ekki reynt enn','%1$s nothing to do.'=>'%1$s ekkert að gera.','%1$s %2$s.'=>'%1$s %2$s.','Bulk download:'=>'Hópniðurhal:','Bulk update:'=>'Hópuppfærsla:','Bulk request:'=>'Hópbeiðni:','per day'=>'á dag','Wrong meaning'=>'Röng merking','Wrong term'=>'Rangt hugtak','Broken placeholder'=>'Bilaður staðgengill','Wrong for this context'=>'Rangt í þessu samhengi','Wrong plural form'=>'Rangt fleirtölusnið','Negation reversed'=>'Neitun snúið við','Translation does not load'=>'Þýðing hleðst ekki','problem report categoryOther'=>'Annað','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','Continuing…'=>'Held áfram…','Continue next batch (%d left)'=>'Halda áfram með næstu lotu (%d eftir)','Search components'=>'Leita í einingum','These are the languages this site uses. You can change them in %s.'=>'Þetta eru tungumálin sem þessi vefur notar. Þú getur breytt þeim í %s.','Upload this component?'=>'Senda þessa einingu inn?','There is no upload waiting for confirmation.'=>'Engin innsending bíður staðfestingar.','Back'=>'Til baka','To translate this component, Babilim needs its source.'=>'Til að þýða þessa einingu þarf Babilim frumkóða hennar.','The entire plugin or theme directory of %1$s (version %2$s) will be uploaded to Babilim.'=>'Öll viðbótar- eða þemamappa %1$s (útgáfa %2$s) verður send til Babilim.','If that directory contains keys, logs or customer data, they will be uploaded too. The service removes common sensitive files (configuration, environment, database dumps, logs, keys) but cannot guarantee it finds everything.'=>'Ef þessi mappa inniheldur lykla, annála eða viðskiptavinagögn verða þau líka send inn. Þjónustan fjarlægir algengar viðkvæmar skrár (stillingar, umhverfi, gagnagrunnsafrit, annála, lykla) en getur ekki tryggt að hún finni allt.','The upload is kept until you ask Babilim to delete it.'=>'Innsendingin er geymd þar til þú biður Babilim um að eyða henni.','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Hún er geymd hjá hýsingaraðila þjónustunnar og unnin af gervigreindarlíkönum til að búa til þýðinguna.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Upprunalegi textinn og þýðingarnar sem gerðar eru úr honum verða veittar öðrum vefjum sem setja upp sömu útgáfu.','By continuing you confirm that you have the right to upload this component.'=>'Með því að halda áfram staðfestir þú að þú hafir rétt til að senda þessa einingu inn.','Upload and request'=>'Senda inn og óska eftir þýðingu','Uploading…'=>'Sendi inn…','Cancel'=>'Hætta við','Uploading'=>'Sendi inn','There is no upload in progress.'=>'Engin innsending er í gangi.','Uploading part %1$d of %2$d…'=>'Sendi hluta %1$d af %2$d…','Continue'=>'Halda áfram','Confirm'=>'Staðfesta','Remove'=>'Fjarlægja','Roll back'=>'Afturkalla','Nothing to confirm.'=>'Ekkert til að staðfesta.','Choose a language'=>'Veldu tungumál','Roll back and report'=>'Afturkalla og tilkynna','Report a problem'=>'Tilkynna vandamál','Nothing to choose.'=>'Ekkert til að velja.','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Veldu tungumálið.','Supplementary translations'=>'Viðbótarþýðingar','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Framlag hverrar einingar til viðbótar fyrir sjálfgefið textalén hverrar staðfærslu.','Component'=>'Eining','Language'=>'Tungumál','Included in index'=>'Innifalið í skránni','Entries'=>'Færslur','Conflicting keys'=>'Lyklar í árekstri','Yes'=>'Já','No — component inactive'=>'Nei — eining óvirk','No — installed version differs from the active one'=>'Nei — uppsetta útgáfan er önnur en sú virka','No — component removed'=>'Nei — eining fjarlægð','No'=>'Nei','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Aðeins netstjóri getur gert þetta, því það breytir þýðingarskrám sem öll vefsvæði á þessu neti deila.','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim gat ekki lokið við að sannreyna þetta vefsvæði (þjónustan náði ekki sambandi við það aftur). Skráning er í bið.','This site already has an active registration that can no longer be recovered automatically.'=>'Þetta vefsvæði er þegar með virka skráningu sem ekki er lengur hægt að endurheimta sjálfkrafa.','Restart registration'=>'Hefja skráningu aftur','Babilim settings'=>'Babilim stillingar','General'=>'Almennt','Advanced'=>'Ítarlegt','Languages'=>'Tungumál','Automatic installs'=>'Sjálfvirkar uppsetningar','Install available translations automatically'=>'Setja upp tiltækar þýðingar sjálfvirkt','On the free plan, only components that already use one of your free slots are installed automatically, so no new slot is taken.'=>'Í ókeypis áskrift eru aðeins einingar sem nota nú þegar eitt af lausu plássunum þínum settar upp sjálfkrafa, þannig að ekkert nýtt pláss er tekið.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Þetta vefsvæði er hluti af fjölsetursneti sem setur ekki upp nýjar þýðingar sjálfkrafa. Þýðingar sem þegar eru uppsettar eru áfram uppfærðar.','Custom overrides'=>'Sérsniðnar yfirskriftir','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Halda eigin þýðingaryfirskriftum mínum þegar öllu er eytt eða þessi viðbót er fjarlægð.','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Þýðingarskrár sem þú setur í %s hafa alltaf forgang yfir skrár frá Babilim. Þær eru varðveittar nema þú afhakir þetta.','Uninstall'=>'Fjarlæging','Delete all Babilim data on uninstall'=>'Eyða öllum Babilim gögnum við fjarlægingu','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Slökkt sjálfgefið: ef viðbótinni er eytt er auðkenni þessa vefsvæðis varðveitt svo hægt sé að endurnýta það við enduruppsetningu.','Account'=>'Reikningur','Save changes'=>'Vista breytingar','Disable Babilim'=>'Gera Babilim óvirkt','Installed translations are kept, but no further checks or downloads will run.'=>'Uppsettar þýðingar eru varðveittar en engar frekari athuganir eða niðurhal fara fram.','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Gera Babilim óvirkt? Uppsettar þýðingar eru varðveittar en engar frekari athuganir eða niðurhal fara fram.','This site is not registered with Babilim yet.'=>'Þetta vefsvæði hefur ekki enn verið skráð hjá Babilim.','This site is already licensed. Reload the page.'=>'Þetta vefsvæði er þegar með leyfi. Endurhlaðið síðuna.','Checkout is not available for this site right now.'=>'Greiðsla er ekki tiltæk fyrir þennan vef núna.','Could not start checkout: %s'=>'Ekki tókst að hefja greiðslu: %s','Babilim is not enabled.'=>'Babilim er ekki virkt.','Not registered yet'=>'Ekki skráð enn','Not verified'=>'Ekki staðfest','Verified'=>'Staðfest','Status'=>'Staða','Licensed'=>'Með leyfi','Partner'=>'Samstarfsaðili','Free'=>'Ókeypis','License'=>'Leyfi','Upgrade this site'=>'Uppfæra þennan vef','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Einskiptiskaup fyrir þessa vefsíðu: %1$s %2$s. Inniheldur allar framtíðaruppfærslur á þýðingum. Greiðslan fer fram í gegnum Paddle í nýjum flipa.','This issues a new restore code and the previous one stops working. Continue?'=>'Þetta gefur út nýjan endurheimtarkóða og sá fyrri hættir að virka. Halda áfram?','Show a new restore code'=>'Sýna nýjan endurheimtarkóða','rc_…'=>'rc_…','Restore code'=>'Endurheimtarkóði','Restore purchase'=>'Endurheimta kaup','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Keyptir þú leyfi fyrir þetta lén áður? Sláðu inn endurheimtarkóðann sem þú fékkst við greiðslu.','That does not look like a restore code.'=>'Þetta lítur ekki út eins og endurheimtarkóði.','This restore code was not recognised for this site.'=>'Þessi endurheimtarkóði þekktist ekki fyrir þennan vef.','Too many attempts. Try again tomorrow.'=>'Of margar tilraunir. Reyndu aftur á morgun.','This site must be verified first.'=>'Fyrst þarf að staðfesta þennan vef.','Could not restore the purchase: %s'=>'Ekki tókst að endurheimta kaupin: %s','Purchase restored. This site is now licensed.'=>'Kaupin voru endurheimt. Þessi vefsíða er nú með leyfi.','This site has no purchase to show a code for.'=>'Engin kaup eru tengd þessum vef sem hægt er að sýna kóða fyrir.','Could not show a new restore code: %s'=>'Ekki tókst að sýna nýjan endurheimtarkóða: %s','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Nýi endurheimtarkóðinn þinn: %s. Geymdu hann á öruggum stað — fyrri kóðinn virkar ekki lengur.','What is sent when Babilim checks this site'=>'Hvað er sent þegar Babilim athugar þessa vefsíðu','(detected)'=>'(greint)','No language is managed yet.'=>'Ekkert tungumál er í umsjón enn.','Babilim adds translations for every language checked here.'=>'Babilim bætir við þýðingum fyrir öll tungumál sem eru valin hér.','Add another language'=>'Bæta við öðru tungumáli','Choose a language…'=>'Veldu tungumál…','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Ekki tókst að hlaða fullum lista yfir WordPress.org staðfærslur frá þjónustunni, því er ekki hægt að bæta við öðru tungumáli núna.','Theme'=>'Þema','Plugin'=>'Viðbót','Free quota'=>'Ókeypis kvóti','Downloads: %1$d/%2$d (%3$s)'=>'Niðurhal: %1$d/%2$d (%3$s)','Supplementary translation index'=>'Skrá yfir viðbótarþýðingar','Built'=>'Smíðað','Included'=>'Innifalið','Excluded'=>'Undanskilið','Already in WordPress core'=>'Þegar í kjarna WordPress','Supplementary translation maintenance'=>'Viðhald viðbótarþýðinga','Maintenance status is not available right now.'=>'Staða viðhalds er ekki tiltæk núna.','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Hreinsun var sett í bið %1$s: %2$s. Engu var eytt.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Síðasta hreinsun %1$s: %2$d nýmerkt, %3$d skrám eytt, %4$d færslum fjarlægðum.','No cleanup has run yet.'=>'Engin hreinsun hefur verið keyrð enn.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Ritun í þýðingaskrána rakst á aðra beiðni á %1$s (%2$s) og var ekki beitt; nýjasta útgáfan var varðveitt.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Ekki tókst að ljúka ritun í þýðingaskrána á %1$s (%2$s) og henni var ekki beitt (%3$s).','Maintenance'=>'Viðhald','Rebuild index now'=>'Endurbyggja atriðaskrána núna','Sweep now'=>'Skanna núna','Danger zone'=>'Hættusvæði','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Fjarlægir allar tungumálaskrár sem Babilim hefur sett upp fyrir allar viðbætur og þemu á þessum vef.','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Fjarlægja allt sem Babilim setti upp? Þetta eyðir öllum tungumálaskrám sem Babilim setti upp fyrir allar viðbætur og þemu á þessum vef.','Remove everything Babilim installed'=>'Fjarlægja allt sem Babilim setti upp','This string is too long to be sent as a report, so no report form is offered for it.'=>'Þessi strengur er of langur til að senda sem skýrslu, því er ekkert skýrslueyðublað í boði fyrir hann.','Category'=>'Flokkur','Choose a category…'=>'Veldu flokk…','Roll back and send report'=>'Afturkalla og senda tilkynningu','Send report'=>'Senda skýrslu','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Sumur texti þessarar einingar er harðkóðaður af höfundi hennar og tungumálapakki getur ekki þýtt hann.','WordPress.org'=>'WordPress.org','Bundled with the theme'=>'Fylgir með þemanu','Bundled with the plugin'=>'Fylgir með viðbótinni','Upload was not accepted'=>'Innsendingin var ekki samþykkt','Upload expired before it finished'=>'Innsendingin rann út áður en henni lauk','No translation'=>'Engin þýðing','Upload in progress — continue or cancel'=>'Innsending í gangi — haltu áfram eða hættu við','Scheduled, waiting to be processed'=>'Áætlað, bíður vinnslu','Translating…'=>'Þýði…','Translation failed'=>'Þýðing mistókst','Free quota used'=>'Ókeypis kvóti notaður','Needs a paid license'=>'Krefst greidds leyfis','Not supported'=>'Ekki studd','Status unknown'=>'Staða óþekkt','translation statusInstalled'=>'Uppsett','Update available'=>'Uppfærsla í boði','Removed after a failed integrity check'=>'Fjarlægt eftir misheppnaða heildarleikaprófun','Installed · built for %s, new version scheduled'=>'Uppsett · smíðað fyrir %s, ný útgáfa á áætlun','Installed · built for a different version, new version scheduled'=>'Uppsett · smíðað fyrir aðra útgáfu, ný útgáfa er tímasett','Installed · built for %s, translating the new version…'=>'Uppsett · smíðað fyrir %s, nýja útgáfan er þýdd…','Installed · built for a different version, translating the new version…'=>'Uppsett · smíðað fyrir aðra útgáfu, nýja útgáfan er í þýðingu…','Installed · built for %1$s, this site has %2$s'=>'Uppsett · smíðað fyrir %1$s, þessi vefur er með %2$s','Installed · built for %s'=>'Uppsett · smíðað fyrir %s','Installed · built for a different version'=>'Uppsett · smíðað fyrir aðra útgáfu','Installed · built for %s, new version failed'=>'Uppsett · smíðað fyrir %s, ný útgáfa mistókst','Installed · built for a different version, new version failed'=>'Uppsett · smíðað fyrir aðra útgáfu, ný útgáfa mistókst','Installed · built for %s, new version needs a paid license'=>'Uppsett · smíðað fyrir %s, ný útgáfa krefst greidds leyfis','Installed · built for a different version, new version needs a paid license'=>'Uppsett · smíðað fyrir aðra útgáfu, ný útgáfa krefst greidds leyfis','Installed · built for %s, free quota used'=>'Uppsett · smíðað fyrir %s, ókeypis kvóti uppurinn','Installed · built for a different version, free quota used'=>'Uppsett · smíðað fyrir aðra útgáfu, ókeypis kvóti uppurinn','translation statusAvailable'=>'Tiltæk','Installed · %s'=>'Uppsett · %s','Available · %s'=>'Tiltæk · %s','Update'=>'Uppfæra','Download'=>'Sækja','Updating…'=>'Uppfæri…','Downloading…'=>'Sæki…','Retry request'=>'Reyna beiðni aftur','Request newer translation'=>'Biðja um nýrri þýðingu','Request translation'=>'Biðja um þýðingu','Requesting…'=>'Bið um…','Requesting a translation uses one of your free slots, unless this component already uses one. A failed translation does not give the slot back.'=>'Þegar beðið er um þýðingu er eitt af lausum plássum þínum notað, nema þessi eining noti þegar eitt. Misheppnuð þýðing skilar ekki plássinu.','If this component does not use one of your free slots yet, requesting a translation uses one. A failed translation does not give the slot back. Continue?'=>'Ef þessi eining notar ekki enn eitt af lausum plássum þínum notar beiðni um þýðingu eitt. Misheppnuð þýðing skilar ekki plássinu. Halda áfram?','No plugins or themes found.'=>'Engar viðbætur eða þemu fundust.','Clear filters'=>'Hreinsa síur','No components match these filters. %s'=>'Engar einingar passa við þessar síur. %s','Select all'=>'Velja allt','All'=>'Allt','Available'=>'Tiltæk','Updates'=>'Uppfærslur','Requestable'=>'Hægt að biðja um','Installed'=>'Uppsett','Plugins'=>'Viðbætur','Themes'=>'Þemu','All languages'=>'Öll tungumál','%d to install'=>'%d til uppsetningar' . "\0" . '%d til uppsetningar','Language:'=>'Tungumál:','Bulk actions apply to every matching language of each selected component.'=>'Magnaðgerðir gilda um öll samsvarandi tungumál hverrar valinnar einingar.','Bulk actions apply only to the selected language of each selected component.'=>'Magnaðgerðir gilda aðeins um valið tungumál hverrar valinnar einingar.','Version %s'=>'Útgáfa %s','Theme · %s'=>'Þema · %s','Plugin · %s'=>'Viðbót · %s','Remove the %2$s translation of %1$s from this site?'=>'Fjarlægja þýðinguna %2$s fyrir %1$s af þessum vef?','Roll back the %2$s translation of %1$s to the previous build?'=>'Færa %2$s þýðinguna á %1$s til baka í fyrri smíð?','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','The registration challenge is not in the expected form.'=>'Skráningaráskorunin er ekki á væntanlegu sniði.','That is not a valid build identifier.'=>'Þetta er ekki gilt smíðakenni.','Refusing to write outside the Babilim language-file directory.'=>'Neita að skrifa utan tungumálaskrámöppu Babilim.','Could not write the downloaded package to disk.'=>'Ekki tókst að skrifa niðurhalaða pakkann á diskinn.','Unexpected HTTP %d response.'=>'Óvænt HTTP-svar %d.','This site\'s URL, so the service can verify you own it.'=>'Vefslóð þessa vefs, svo þjónustan geti staðfest að þú eigir hann.','Your WordPress version, to serve compatible translation files.'=>'WordPress-útgáfa þín, til að afhenda samhæfðar þýðingarskrár.','Your PHP version, for compatibility.'=>'PHP-útgáfa þín, vegna samhæfni.','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Útgáfa þessarar viðbótar sjálfrar, svo þjónustan geti beðið þig um að uppfæra hana ef hún er of gömul til að eiga samskipti við hana.','This site\'s configured locale.'=>'Stillt staðfærsla þessa vefs.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Sérhver staðfærsla í notkun á þessum vef (staðfærsla vefsins, uppsettir tungumálapakkar, staðfærslur notenda og þær sem þú bætir við handvirkt). Engin staðfærsla er meðhöndluð öðruvísi en önnur.','(a public key generated for this site)'=>'(opinber lykill sem var búinn til fyrir þennan vef)','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'Opinber uppsetningarlykill þessa vefs, notaður til að sanna að beiðnir komi í raun frá þessum vef. Aðeins opinberi helmingurinn er sendur.','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'Sérhver uppsett viðbót/þema: slug, útgáfa, textalén, hvort það er skráð á wp.org, eigin innbyggðar staðfærslur og fyrir hvaða staðfærslur þú hefur þegar sett upp Babilim-þýðingu.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: that component\'s entire directory, as a zip.'=>'Aðeins þegar þú staðfestir innsendingu fyrir viðbót eða þema sem er ekki á WordPress.org: öll mappa þeirrar einingar, sem zip-skrá.','(generic codes and coordinates only)'=>'(aðeins almennir kóðar og hnit)','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'Allt að 20 biðandi greiningaratburðir (t.d. skrá sem féll á heildarleikaprófun), hver með aðeins kóða, einingu og staðfærslu, og aldrei neitt textaefni eða þýddan texta.','Unsafe locale: %s'=>'Óörugg staðfærsla: %s','Manifest unavailable: %s'=>'Manifest ekki tiltækt: %s','Could not determine active components; the existing merged index was left unchanged.'=>'Ekki tókst að ákvarða virkar einingar; núverandi sameinaða skráin var látin óbreytt.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Ekki tókst að ákvarða uppsettar viðbætur/þemu; hreinsun sleppt, engu var eytt.','Sweep aborted without orphaning anything: %s.'=>'Hreinsun hætt án þess að nokkuð yrði munaðarlaust: %s.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Hreinsunin keyrði, en ekki var hægt að skrá allar breytingar hennar í þýðingaskrána; næsta hreinsun reynir aftur.','component kind in the sweep brake messagetheme'=>'þema','component kind in the sweep brake messageplugin'=>'viðbót','it would orphan every managed %1$s component (%2$d of %2$d)'=>'það myndi gera sérhverja stýrða einingu af gerðinni %1$s munaðarlausa (%2$d af %2$d)','it would orphan %1$d of %2$d managed components (more than half)'=>'það myndi gera %1$d af %2$d stýrðum einingum munaðarlausar (meira en helming)','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'Sameinaða skráin fyrir \'%s\' var endurbyggð, en þýðingaskráin gat ekki skráð hana; næsta endurbygging reynir aftur.','Could not write the staged merged index.'=>'Ekki tókst að skrifa undirbúnu sameinuðu skrána.','Re-parsed entry count did not match the built index.'=>'Fjöldi færslna eftir endurtúlkun passaði ekki við byggðu skrána.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Ekki tókst að færa sameinuðu skrána fyrir \'%s\' á sinn stað; fyrri skráin sem var í notkun (ef einhver) var fjarlægð frekar en að skilja hana eftir hálfuppfærða. Engin viðbót fyrir sjálfgefið textalén er veitt fyrir þessa staðfærslu fyrr en næsta vel heppnaða endurbygging.','Could not open zip: %s'=>'Ekki tókst að opna zip: %s','Zip has no manifest.json.'=>'Zip-skráin hefur enga manifest.json.','manifest.json in the zip is not valid JSON.'=>'manifest.json í zip-skránni er ekki gilt JSON.','manifest.json\'s \'%s\' does not match the expected value.'=>'\'%s\' í manifest.json samsvarar ekki væntanlegu gildi.','Another installation is running; try again in a moment.'=>'Önnur uppsetning er í gangi; reyndu aftur eftir augnablik.','Not a valid server_build_id: %s'=>'Ekki gilt server_build_id: %s','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Tegund \'%1$s\' í manifest pakkans samsvarar ekki umbeðinni tegund \'%2$s\'.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Textalén pakkans \'%1$s\' samsvarar ekki eintaki þessa vefs af einingunni (\'%2$s\', þannig að hann var ekki settur upp.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Uppgefið lén \'%1$s\' samsvarar hvorki slug \'%2$s\' í manifest pakkans né text_domain \'%3$s\'.','Unsafe slug: %s'=>'Óöruggt slug: %s','Unsafe text_domain: %s'=>'Óöruggt text_domain: %s','The package has no %s for its own text domain.'=>'Pakkinn hefur ekkert %s fyrir eigið textalén.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json vantar eða hefur ógilt \'%s\'.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json vantar eða hefur ógilt \'entries\'.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json vantar eða er með ógilt \'files\'.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json vantar eða er með ógilt \'extra_domains\'.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json vantar eða er með ógilt \'build_no\'.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\' í manifest.json er ekki gilt build-auðkenni.','manifest.json\'s \'contract\' is not a valid version string.'=>'\'contract\' í manifest.json er ekki gild útgáfustrengur.','manifest.json\'s \'status\' must be \'published\'.'=>'Reiturinn „status“ í manifest.json verður að hafa gildið „published“.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'\'kind\' í manifest.json verður að vera \'plugin\' eða \'theme\'.','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json er með ógilt \'default_domain_entries\'.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json er með ógilt \'default_domain_files\'.','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest vantar eða er með ógilt \'%s\'.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\' í expected_manifest er ekki gilt build-auðkenni.','No record for %s'=>'Engin færsla fyrir %s','One or more served files no longer match the manifest.'=>'Ein eða fleiri afgreiddar skrár passa ekki lengur við manifest.','No previous build to roll back to.'=>'Engin fyrri útgáfa til að snúa aftur til.','The change could not be recorded in the translation index; please try again.'=>'Ekki tókst að skrá breytinguna í þýðingaskrána; reyndu aftur.','Unknown kind: %s'=>'Óþekkt tegund: %s','Unsafe domain: %s'=>'Óöruggt lén: %s','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'Textalénið \'%1$s\' (%2$s) er þegar í notkun fyrir aðra uppsetta einingu (%3$s); ekkert var sett upp.','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Afturköllun myndi skrifa yfir \'%1$s\' (%2$s), sem er nú afgreidd fyrir aðra uppsetta einingu (%3$s); engu var breytt.','Zip is missing expected file: %s'=>'Zip-skrána vantar væntanlega skrá: %s','sha256 mismatch for %s'=>'sha256 stemmir ekki fyrir %s','The package declares no main translation file.'=>'Pakkinn tilgreinir enga aðalþýðingarskrá.','Zip is missing expected default file: %s'=>'Zip-skrána vantar væntanlega sjálfgefna skrá: %s','sha256 mismatch for default/%s'=>'sha256 stemmir ekki fyrir default/%s','Could not stage %s'=>'Ekki tókst að undirbúa %s','Could not stage default/%s'=>'Ekki tókst að undirbúa default/%s','Entry count mismatch for %s'=>'Fjöldi færslna passar ekki fyrir %s','Could not verify entry count for %s'=>'Ekki tókst að staðfesta fjölda færslna fyrir %s','l10n.php entry count mismatch for %s'=>'Fjöldi færslna í l10n.php stemmir ekki fyrir %s','Default supplement entry count mismatch.'=>'Fjöldi færslna í sjálfgefnu viðbótinni passar ekki.','The package produced no servable main translation file.'=>'Pakkinn bjó ekki til neina nothæfa aðalþýðingarskrá.','Could not prepare %s for rollback.'=>'Ekki tókst að undirbúa %s fyrir afturköllun.','Could not back up %s before replacing it.'=>'Ekki tókst að taka afrit af %s áður en henni var skipt út.','Could not move %s into place.'=>'Ekki tókst að færa %s á sinn stað.','Could not read %s back after moving it into place.'=>'Ekki tókst að lesa %s aftur eftir að hún var færð á sinn stað.','English (United States)'=>'enska (Bandaríkin)','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest er ekki tiltækt: %s','could not read _manifest.json: %s'=>'gat ekki lesið _manifest.json: %s','failed to parse _manifest.json: %s'=>'Tókst ekki að þátta _manifest.json: %s','_manifest.json has an unexpected structure'=>'_manifest.json hefur óvænta uppbyggingu','Could not create the package archive.'=>'Ekki tókst að búa til pakkasafnið.','No writable temporary directory is available for packaging.'=>'Engin skrifanleg tímabundin mappa er tiltæk fyrir pökkun.','A file in the component could not be read, so it was not packaged.'=>'Ekki tókst að lesa skrá í einingunni og hún var því ekki pökkuð.','Only plugins and themes can be packaged.'=>'Aðeins viðbætur og þemu er hægt að pakka.','The component\'s main file was not found.'=>'Aðalskrá einingarinnar fannst ekki.','The component is not inside the plugins or themes directory.'=>'Einingin er ekki í viðbóta- eða þemamöppunni.','Babilim ran out of time for this step and will continue on the next check.'=>'Tíminn sem Babilim hafði til að ljúka þessu skrefi rann út og Babilim heldur áfram við næstu athugun.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim gat ekki staðfest þennan vef, því er engu hlaðið niður eða sett upp fyrr en staðfesting tekst.','Registration response was missing required fields.'=>'Í skráningarsvarinu vantaði nauðsynlega reiti.','No pending challenge to verify.'=>'Engin bíðandi áskorun til að staðfesta.','Verify response was missing site_token.'=>'Í staðfestingarsvarinu vantaði site_token.','No site id is on file to rotate a token for.'=>'Ekkert vefauðkenni er skráð sem hægt er að endurnýja aðgangstákn fyrir.','Rotate-token response was missing site_token.'=>'Í svarinu við skiptingu tákns vantaði site_token.','nonce must be a hexadecimal string.'=>'nonce verður að vera sextándakerfisstrengur.','No pending challenge for this nonce.'=>'Engin bíðandi áskorun fyrir þetta nonce.','Too many requests.'=>'Of margar beiðnir.','The service asked this site to wait before syncing again.'=>'Þjónustan bað þennan vef um að bíða áður en hann samstillir aftur.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Þessi vefur er með %1$d einingar á %2$d tungumálum, sem krefst %3$d athugunarlota; Babilim getur séð um í mesta lagi %4$d í hverri keyrslu. Fækkaðu stýrðum tungumálum í stillingum eða gerðu ónotuð viðbætur og þemu óvirk, og ýttu síðan á Athuga aftur núna.','Babilim could not finish checking this site.'=>'Babilim gat ekki lokið við að athuga þennan vef.','This site\'s address is too long for Babilim to register.'=>'Vistfang þessa vefs er of langt til að Babilim geti skráð það.','This site\'s locale code is not one Babilim can register.'=>'Staðfærslukóði þessa vefs er ekki einn sem Babilim getur skráð.','The download response was missing a usable location.'=>'Í niðurhalssvarinu vantaði nothæfa staðsetningu.','The service\'s upload offer was incomplete.'=>'Upphleðslutilboð þjónustunnar var ófullnægjandi.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Þessi eining er stærri en þjónustan tekur við og því er ekki hægt að hlaða henni upp.','The packaged component could not be read.'=>'Ekki tókst að lesa pakkaða eininguna.','A part of the upload kept failing, so the upload was cancelled.'=>'Hluti upphleðslunnar mistókst ítrekað og hætt var við upphleðsluna.','Could not read: %s'=>'Ekki tókst að lesa: %s']];